import useFetch from './hooks/useFetch.js';
impor

function Quotes () {

   const url = 'https://zenquotes.io/api/today';

    const { data, isPending, error } = useFetch(url);

    return (
        <div className="width-fit bg-white-opacity-30">
            {isPending && <div className='text-white'>Loading quote...</div>}
            {error && <div className='text-white'>Error loading quote</div>}
            {data && <div className='text-white'>{data[0].q} - {data[0].a}</div>}
        </div>
    )
}

export default Quotes
